-- =====================================================================
-- 261 — Lote 2 LNME (2/6): perfis em public.drug_profiles (1/2)
-- ---------------------------------------------------------------------
-- Conteúdo autoral (não copiado), ancorado nos rótulos aprovados
-- DailyMed (setIDs validados na API — nenhum fictício) e corroborado
-- no Prontuário Terapêutico do INFARMED (11.ª ed., 2012).
-- Padrão 7.6: JOIN (VALUES) ON d.slug = v.slug + ON CONFLICT DO NOTHING.
-- Idempotente. Companheiras: 260 (drugs), 262 (perfis 2/2), 263
-- (farmacologia).
-- =====================================================================

INSERT INTO public.drug_profiles
  (drug_id, overview_public_pt, overview_public_en, overview_pro_pt, overview_pro_en,
   indications_pt, indications_en, side_effects_pt, side_effects_en,
   precautions_pt, precautions_en, source_pt, source_en, status)
SELECT d.id, v.overview_public_pt, v.overview_public_en, v.overview_pro_pt, v.overview_pro_en,
       v.indications_pt, v.indications_en, v.side_effects_pt, v.side_effects_en,
       v.precautions_pt, v.precautions_en, v.source_pt, v.source_en, 'published'
FROM public.drugs d
JOIN (VALUES
  ('amoxicilina-acido-clavulanico',
   E'Amoxicilina + ácido clavulânico é um antibiótico de largo espetro que combina uma penicilina com uma substância que anula as defesas de muitas bactérias resistentes. Trata infeções do ouvido, seios da face, pulmão, urina, pele e dentes.',
   E'Amoxicillin + clavulanic acid is a broad-spectrum antibiotic combining a penicillin with a substance that defeats the defences of many resistant bacteria. It treats ear, sinus, lung, urinary, skin and dental infections.',
   E'Associação de aminopenicilina com inibidor de beta-lactamases (clavulanato). O clavulanato alarga o espetro da amoxicilina a estirpes produtoras de beta-lactamase (H. influenzae, M. catarrhalis, anaeróbios, S. aureus sensível). Absorção oral boa; dose ajustada na função renal.',
   E'Aminopenicillin combined with a beta-lactamase inhibitor (clavulanate). Clavulanate extends amoxicillin\u2019s spectrum to beta-lactamase-producing strains (H. influenzae, M. catarrhalis, anaerobes, sensitive S. aureus). Good oral absorption; dose adjusted for renal function.',
   E'• Otitis média e sinusite bacterianas\\n• Exacerbação bacteriana de DPOC e pneumonia adquirida na comunidade\\n• Infeções urinárias (incl. pielonefrite)\\n• Celulite e mordeduras infetadas\\n• Abscesso dentário e periodontite',
   E'• Bacterial otitis media and sinusitis\\n• Bacterial exacerbation of COPD and community-acquired pneumonia\\n• Urinary tract infections (incl. pyelonephritis)\\n• Cellulitis and infected bites\\n• Dental abscess and periodontitis',
   E'• Náuseas, vómitos e diarreia (os mais frequentes)\\n• Candidíase oral ou vaginal\\n• Erupção cutânea (mais frequente do que com amoxicilina isolada)\\n• Colite associada a antibióticos (Clostridioides difficile) — raro\\n• Ictericia colestática e elevação de transaminases (raro, sobretudo em idosos e tratamentos > 2 semanas)\\n• Procure ajuda imediata se houver sinais de reação alérgica grave (dificuldade em respirar, inchaço do rosto/garganta).',
   E'• Nausea, vomiting and diarrhoea (the most common)\\n• Oral or vaginal thrush\\n• Skin rash (more common than with amoxicillin alone)\\n• Antibiotic-associated colitis (Clostridioides difficile) — rare\\n• Cholestatic jaundice and transaminase elevation (rare, especially in the elderly and courses > 2 weeks)\\n• Seek immediate help if there are signs of a severe allergic reaction (trouble breathing, face/throat swelling).',
   E'• Antecedente de ictericia/hepatite com esta associação contraindica nova exposição\\n• Questionar alergia à penicilina antes de prescrever\\n• Tomar no início das refeições para reduzir desconforto gástrico\\n• Em mononucleose infecciosa, risco elevado de erupção',
   E'• Previous jaundice/hepatitis with this combination contraindicates re-exposure\\n• Ask about penicillin allergy before prescribing\\n• Take at the start of meals to reduce gastric discomfort\\n• In infectious mononucleosis, high rash risk',
   E'Rótulo aprovado DailyMed/FDA — Amoxicillin and Clavulanate Potassium Tablet: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1bda03a2-6c7d-4c9e-b98a-e5e01bebb3b1 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — Amoxicillin and Clavulanate Potassium Tablet: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1bda03a2-6c7d-4c9e-b98a-e5e01bebb3b1 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),

  ('tetracaina',
   E'Tetracaína é um anestésico local aplicado na pele ou nas mucosas para adormecer a zona antes de pequenas intervenções: gotas nos olhos, pomadas na pele, sprays na garganta. Age em minutos e o efeito dura cerca de 30–60 minutos.',
   E'Tetracaine is a local anaesthetic applied to skin or mucous membranes to numb the area before minor procedures: eye drops, skin ointments, throat sprays. It works within minutes and the effect lasts about 30–60 minutes.',
   E'Éster de ácido para-aminobenzoico (PABA) que bloqueia os canais de sódio dos nervos periféricos, impedindo a despolarização e a condução da dor. Potência elevada, início relativamente lento e duração longa; absorção sistémica significativa em mucosas hiperemiadas — risco de toxicidade sistémica superior ao dos amidas em aplicações extensas.',
   E'Para-aminobenzoic acid (PABA) ester that blocks peripheral nerve sodium channels, preventing depolarisation and pain conduction. High potency, relatively slow onset and long duration; significant systemic absorption on inflamed mucosa — systemic toxicity risk higher than amides in extensive application.',
   E'• Anestesia tópica ocular (tonometria, remoção de corpo estranho, cirurgia curta)\\n• Anestesia tópica de pele antes de punção venosa ou pequenas suturas\\n• Anestesia de mucosas ORL (nasofaringe, laringe) em procedimentos diagnósticos',
   E'• Ocular topical anaesthesia (tonometry, foreign body removal, short surgery)\\n• Skin topical anaesthesia before venepuncture or minor suturing\\n• ENT mucosal anaesthesia (nasopharynx, larynx) in diagnostic procedures',
   E'• Irritação, ardor ou vermelhidão no local (transitórios)\\n• Olho: visível turvação temporária e aumento da sensibilidade à luz\\n• Reações de hipersensibilidade (mais frequentes que com amidas, pela fração PABA)\\n• Toxicidade sistémica (tonturas, zumbidos, convulsões, arritmias) em doses excessivas ou superfícies extensas\\n• Procure ajuda imediata se houver sinais de reação alérgica grave (dificuldade em respirar, inchaço do rosto/garganta).',
   E'• Local irritation, burning or redness (transient)\\n• Eye: temporary blurred vision and light sensitivity\\n• Hypersensitivity reactions (more frequent than with amides, due to the PABA moiety)\\n• Systemic toxicity (dizziness, tinnitus, seizures, arrhythmias) with excessive doses or extensive surfaces\\n• Seek immediate help if there are signs of a severe allergic reaction (trouble breathing, face/throat swelling).',
   E'• Não usar em olho com infeção ou lesão corneana extensa (retarda epitelização)\\n• Nunca injetar por via parentérica — apenas uso tópico\\n• Cuidado com doses repetidas em mucosas (absorção rápida)\\n• Em doentes alérgicos a ésteres (benzocaína, procaína), usar um amida',
   E'• Do not use in an infected eye or with extensive corneal damage (delays re-epithelialisation)\\n• Never inject parenterally — topical use only\\n• Caution with repeated mucosal doses (rapid absorption)\\n• In patients allergic to esters (benzocaine, procaine), use an amide',
   E'Rótulo aprovado DailyMed/FDA — Tetracaine Hydrochloride Solution: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=01fba5f8-a60a-444c-9abd-299540b8815a — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — Tetracaine Hydrochloride Solution: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=01fba5f8-a60a-444c-9abd-299540b8815a — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),

  ('bicarbonato-sodio',
   E'Bicarbonato de sódio é uma solução/comprimido que corrige o excesso de ácido no sangue (acidose) e serve também como antiácido ocasional e para alcalinizar a urina em certas intoxicações.',
   E'Sodium bicarbonate is a solution/tablet that corrects excess acid in the blood (acidosis) and also serves as an occasional antacid and to alkalinise urine in certain poisonings.',
   E'Alcalinizante sistémico: tampona prótons H+ elevando o pH plasmático e o bicarbonato sérico. Corrige acidose metabólica; por via oral alcaliniza a urina (tratamento de intoxicações por fármacos ácidos e uropatia por cistina) e neutraliza HCl gástrico. Dosagem guiada por gasimetria; excesso gera alcalose, hipernatremia e sobrecarga de volume.',
   E'Systemic alkalinising agent: buffers H+ protons, raising plasma pH and serum bicarbonate. Corrects metabolic acidosis; orally it alkalinises urine (treatment of acidic drug poisonings and cystinuria) and neutralises gastric HCl. Dosing guided by blood gas analysis; excess causes alkalosis, hypernatraemia and volume overload.',
   E'• Acidose metabólica confirmada (gravidade médica)\\n• Hiperpotassemia (desvio do K+ para dentro da célula)\\n• Alcalinização urinária em intoxicações (fenobarbital, salicilatos)\\n• Antiácido ocasional na dispepsia (uso oral breve)',
   E'• Confirmed metabolic acidosis (medical setting)\\n• Hyperkalaemia (K+ shift into cells)\\n• Urinary alkalinisation in poisonings (phenobarbital, salicylates)\\n• Occasional antacid in dyspepsia (brief oral use)',
   E'• Gosto metálico, eructações e distensão (uso oral)\\n• Alcalose metabólica (cãibras, tetania, confusão) em excesso\\n• Hipernatremia e sobrecarga de volume (edema, insuficiência cardíaca) com perfusão IV rápida\\n• Extravasamento IV: necrose tecidual (solução concentrada)\\n• Procure ajuda imediata se houver dificuldade em respirar ou confusão marcada após perfusão.',
   E'• Metallic taste, belching and bloating (oral use)\\n• Metabolic alkalosis (cramps, tetany, confusion) in excess\\n• Hypernatraemia and volume overload (oedema, heart failure) with rapid IV infusion\\n• IV extravasation: tissue necrosis (concentrated solution)\\n• Seek immediate help if breathing difficulty or marked confusion occurs after infusion.',
   E'• Não usar como "reanimação universal" — indicação específica em paragem prolongada com acidose documentada\\n• Vigiar potássio, sódio e cálcio ionizado durante perfusões\\n• Cuidado em insuficiência renal, cardíaca e hepática (retenção de sódio)\\n• Incompatível com soluções de cálcio (precipitação)',
   E'• Not a universal "resuscitation drug" — specific indication in prolonged arrest with documented acidosis\\n• Monitor potassium, sodium and ionised calcium during infusions\\n• Caution in renal, cardiac and hepatic failure (sodium retention)\\n• Incompatible with calcium solutions (precipitation)',
   E'Rótulo aprovado DailyMed/FDA — Sodium Bicarbonate Tablet (antacid): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=28cdf049-acdb-4098-a5ca-e86257c81954 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — Sodium Bicarbonate Tablet (antacid): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=28cdf049-acdb-4098-a5ca-e86257c81954 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),

  ('clorexidina',
   E'Clorexidina é um antisséptico usado para limpar e desinfetar a pele, as mucosas e a boca: lavagem das mãos dos profissionais, preparação da pele antes de injeções e cirurgias, e bochechos para infeções da gengiva.',
   E'Chlorhexidine is an antiseptic used to clean and disinfect skin, mucous membranes and the mouth: healthcare hand washing, skin preparation before injections and surgery, and mouthwashes for gum infections.',
   E'Biguanida catiónica que rompe as membranas de bactérias (broad espetro gram+/gram−, com boa atividade residual) e fungos. Não é ativa de forma fiável contra esporos. A ação residual na pele dura várias horas, o que a distingue do álcool isolado. Inativada por sabões aniónicos e matéria orgânica; as formulações alcoólicas são mais eficazes na pele íntegra.',
   E'Cationic biguanide that disrupts bacterial membranes (broad gram+/gram− spectrum, with good residual activity) and fungi. Not reliably sporicidal. Skin residual action lasts several hours, which distinguishes it from alcohol alone. Inactivated by anionic soaps and organic matter; alcoholic formulations are more effective on intact skin.',
   E'• Antissepsia das mãos e da pele antes de procedimentos invasivos\\n• Preparação pré-operatória da pele e duche pré-cirúrgico\\n• Bochechos na gengivite e mucosite (formulação oral)\\n• Higiene do cordão umbilical do recém-nascido (programas de saúde pública)',
   E'• Hand and skin antisepsis before invasive procedures\\n• Pre-operative skin preparation and pre-surgical shower\\n• Mouthwashes in gingivitis and mucositis (oral formulation)\\n• Newborn umbilical cord hygiene (public health programmes)',
   E'• Irritação cutânea leve e dermatite de contacto\\n• Manter fora dos olhos e ouvidos internos (lesão de córnea/timpano)\\n• Bochecho: alteração do gosto, manchas na língua e dentes (reversíveis), pedraria nos dentes\\n• Raro: reação alérgica grave (anafilaxia) descrita com formulações IV/urus\\n• Procure ajuda imediata se houver sinais de reação alérgica grave (dificuldade em respirar, inchaço do rosto/garganta).',
   E'• Mild skin irritation and contact dermatitis\\n• Keep away from eyes and inner ears (corneal/tympanic damage)\\n• Mouthwash: taste disturbance, tongue and teeth staining (reversible), tartar\\n• Rare: severe allergic reaction (anaphylaxis) described with certain formulations\\n• Seek immediate help if there are signs of a severe allergic reaction (trouble breathing, face/throat swelling).',
   E'• Nunca injetar ou usar em meninges, olho ou ouvido médio\\n• Não aplicar depois de sabão comum (inativação) — enxaguar primeiro\\n• Evitar contacto prolongado com meninges e sistema nervoso central\\n• Solução oral: não engolir; uso limitado a 2–3 semanas sob orientação',
   E'• Never inject or use on meninges, eye or middle ear\\n• Do not apply after ordinary soap (inactivation) — rinse first\\n• Avoid prolonged contact with meninges and central nervous system\\n• Oral solution: do not swallow; limit use to 2–3 weeks under guidance',
   E'Rótulo aprovado DailyMed/FDA — Chlorhexidine Gluconate Rinse: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7e3862b9-3786-4cfe-bfad-c992a7038eca — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — Chlorhexidine Gluconate Rinse: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7e3862b9-3786-4cfe-bfad-c992a7038eca — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),

  ('iodopovidona',
   E'Iodopovidona (PVPI) é um antisséptico de cor castanha usado para desinfetar a pele antes de injeções, cirurgias e no tratamento de feridas. Também existe em forma de solução para bochechos e para lavagens ginecológicas.',
   E'Povidone-iodine (PVP-I) is a brown-coloured antiseptic used to disinfect skin before injections and surgery and to treat wounds. It also comes as mouthwash solutions and gynaecological washes.',
   E'Iodóforo: o iodo liberado lentamente da povidona oxida proteínas bacterianas e esporos, com espetro amplo (bactérias, fungos, vírus, esporos — único antisséptico com boa atividade esporicida). Eficácia reduzida em presença de sangue/pus; ação residual mínima comparada com a clorexidina. Absorção sistémica de iodo possível em mucosas extensas ou queimaduras (riscos tiroideus e renais).',
   E'Iodophor: iodine slowly released from povidone oxidises bacterial proteins and spores, with a broad spectrum (bacteria, fungi, viruses, spores — the only antiseptic with good sporicidal activity). Efficacy reduced by blood/pus; minimal residual action compared with chlorhexidine. Systemic iodine absorption possible on extensive mucosa or burns (thyroid and renal risks).',
   E'• Antissepsia pré-operatória da pele e mucosas\\n• Desinfeção de feridas e queimaduras superficiais\\n• Bochechos e gargarejos em faringites (formulação oral)\\n• Higiene vaginal medicada (douche, sob indicação)',
   E'• Pre-operative skin and mucosa antisepsis\\n• Disinfection of superficial wounds and burns\\n• Mouthwashes and gargles in pharyngitis (oral formulation)\\n• Medicated vaginal hygiene (douche, when indicated)',
   E'• Irritação local e coloração temporária da pele (sai com água e sabão)\\n• Dermatite de contacto iodada\\n• Bochecho prolongado: alteração do gosto e aumento do risco de disfunção tiroidea (absorção)\\n• Reações alérgicas ao iodo (raro)\\n• Procure ajuda imediata se houver sinais de reação alérgica grave (dificuldade em respirar, inchaço do rosto/garganta).',
   E'• Local irritation and temporary skin staining (removes with soap and water)\\n• Iodine contact dermatitis\\n• Prolonged gargling: taste disturbance and increased thyroid dysfunction risk (absorption)\\n• Iodine allergic reactions (rare)\\n• Seek immediate help if there are signs of a severe allergic reaction (trouble breathing, face/throat swelling).',
   E'• Evitar uso extenso em queimaduras grandes, recém-nascidos e grávidas (absorção de iodo → hipotiroidismo fetal/neonatal)\\n• Não usar em doentes com doença tiroideia não controlada sem avaliação\\n• Não combinar com clorexidina (incompatibilidade química)\\n• Não cobrir com oclusão hermética após aplicação extensa',
   E'• Avoid extensive use on large burns, newborns and pregnant women (iodine absorption → fetal/neonatal hypothyroidism)\\n• Do not use in patients with uncontrolled thyroid disease without assessment\\n• Do not combine with chlorhexidine (chemical incompatibility)\\n• Avoid airtight occlusion after extensive application',
   E'Rótulo aprovado DailyMed/FDA — Povidone Iodine: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=76b15f6a-51d6-45ec-b6cb-8b10a08ed32a — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — Povidone Iodine: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=76b15f6a-51d6-45ec-b6cb-8b10a08ed32a — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),

  ('sulfato-zinco',
   E'Sulfato de zinco é um suplemento mineral usado para corrigir a falta de zinco, que pode causar atraso de crescimento, diarreia persistente e defesas baixas. Em Angola, é sobretudo dado a crianças com diarreia, junto com sais de reidratação oral.',
   E'Zinc sulfate is a mineral supplement used to correct zinc deficiency, which can cause growth delay, persistent diarrhoea and low immunity. In Angola, it is mainly given to children with diarrhoea, together with oral rehydration salts.',
   E'Zinco é cofactor de mais de 300 enzimas (metabolismo do ADN, imunidade, cicatrização, paladar). A suplementação na diarreia infantil reduz a duração do episódio e o risco de recidiva nos 2–3 meses seguintes. Absorção intestinal competitiva com ferro e cobre — tratamentos prolongados exigem atenção ao cobre.',
   E'Zinc is a cofactor of over 300 enzymes (DNA metabolism, immunity, wound healing, taste). Supplementation in childhood diarrhoea shortens the episode and reduces recurrence risk over the following 2–3 months. Intestinal absorption competes with iron and copper — prolonged treatment requires copper attention.',
   E'• Diarreia aguda em crianças (adjuvante dos SRO, 10–20 mg/dia por 10–14 dias)\\n• Deficiência de zinco documentada (acrodermatite enteropática, nutrição parentérica)\\n• Adjuvante na cicatrização de úlceras e feridas crónicas com défice de zinco\\n• Redução do risco de pneumonia e infeções respiratórias em crianças desnutridas (programas de saúde pública)',
   E'• Acute diarrhoea in children (adjunct to ORS, 10–20 mg/day for 10–14 days)\\n• Documented zinc deficiency (acrodermatitis enteropathica, parenteral nutrition)\\n• Adjunct in healing of ulcers and chronic wounds with zinc deficiency\\n• Reduced risk of pneumonia and respiratory infections in malnourished children (public health programmes)',
   E'• Náuseas, vómitos e desconforto gástrico (melhor com alimento)\\n• Gosto metálico\\n• Tratamentos longos em dose alta: deficiência de cobre, queda do HDL\\n• Sobredosagem crónica: anemia e neuropatia (excesso de zinco bloqueia o cobre)\\n• Procure ajuda imediata se houver sinais de reação alérgica grave (dificuldade em respirar, inchaço do rosto/garganta).',
   E'• Nausea, vomiting and gastric discomfort (better with food)\\n• Metallic taste\\n• Long high-dose treatment: copper deficiency, lower HDL\\n• Chronic overdose: anaemia and neuropathy (excess zinc blocks copper)\\n• Seek immediate help if there are signs of a severe allergic reaction (trouble breathing, face/throat swelling).',
   E'• Espaçar da toma de ferro, antibióticos (quinolonas, tetraciclinas) e penicilamina em pelo menos 2 h\\n• Não ultrapassar 40 mg/dia de zinco elementar no adulto sem indicação\\n• Em diarreia infantil, completar os 10–14 dias mesmo com melhoria rápida\\n• Vigiar cobre sérico em tratamentos > 3 meses',
   E'• Space 2 h apart from iron, antibiotics (quinolones, tetracyclines) and penicillamine\\n• Do not exceed 40 mg/day of elemental zinc in adults without indication\\n• In childhood diarrhoea, complete the 10–14 days even with rapid improvement\\n• Monitor serum copper for treatments > 3 months',
   E'Rótulo aprovado DailyMed/FDA — Zinc Sulfate Injection [Apotex]: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=b9cf2dab-6ec8-e099-464a-af46a3601971 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — Zinc Sulfate Injection [Apotex]: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=b9cf2dab-6ec8-e099-464a-af46a3601971 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),

  ('acido-ascorbico',
   E'Ácido ascórbico (vitamina C) é uma vitamina essencial para a cicatrização, o colagénio e as defesas. A falta grave causa escorbuto. Serve também para aumentar a absorção do ferro nos tratamentos de anemia.',
   E'Ascorbic acid (vitamin C) is an essential vitamin for healing, collagen and immunity. Severe deficiency causes scurvy. It is also used to boost iron absorption in anaemia treatment.',
   E'Co-factor redox de hidroxilases do colagénio, da carnitina e da catecolamina; potente antioxidante hidrossolúvel. Melhora a absorção do ferro não-hémico por redução do Fe3+ a Fe2+ no duodeno. Excesso (geralmente > 1 g/dia) é excretado na urina; metabolito oxalato pode litiasar.',
   E'Redox cofactor of collagen, carnitine and catecholamine hydroxylases; potent water-soluble antioxidant. Improves non-haem iron absorption by reducing Fe3+ to Fe2+ in the duodenum. Excess (usually > 1 g/day) is excreted in urine; the oxalate metabolite can form stones.',
   E'• Tratamento e prevenção do escorbuto\\n• Adjuvante da absorção de ferro na anemia ferropénica\\n• Deficiência documentada (desnutrição, alcoolismo, diálise)\\n• Suplementação em dietas pobres em fruta/legumes frescos',
   E'• Treatment and prevention of scurvy\\n• Adjunct to iron absorption in iron-deficiency anaemia\\n• Documented deficiency (malnutrition, alcoholism, dialysis)\\n• Supplementation in diets poor in fresh fruit/vegetables',
   E'• Doses altas: diarreia osmótica, desconforto gástrico, flatulência\\n• Litíase renal de oxalato (risco em tratamentos crónicos > 1 g/dia)\\n• Hemólise em doentes com défice de G6PD em dose IV elevada (raro)\\n• Procure ajuda imediata se houver sinais de reação alérgica grave (dificuldade em respirar, inchaço do rosto/garganta).',
   E'• High doses: osmotic diarrhoea, gastric discomfort, flatulence\\n• Oxalate kidney stones (risk with chronic courses > 1 g/day)\\n• Haemolysis in G6PD-deficient patients at high IV doses (rare)\\n• Seek immediate help if there are signs of a severe allergic reaction (trouble breathing, face/throat swelling).',
   E'• Cuidado em insuficiência renal e história de cálculos de oxalato\\n• Espaçar da vitamina B12 em doses altas crónicas (interferência laboratorial)\\n• Doses > 500 mg/dia raramente acrescentam benefício\\n• Interfere com testes de glucose urinária (falso-negativos) e escondem sangue nas fezes',
   E'• Caution in renal failure and history of oxalate stones\\n• Space from vitamin B12 in chronic high doses (laboratory interference)\\n• Doses > 500 mg/day rarely add benefit\\n• Interferes with urine glucose tests (false negatives) and faecal occult blood',
   E'Rótulo aprovado DailyMed/FDA — Ascor L 500 (Ascorbic Acid Injection): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=2b71bd05-2891-34f2-e054-00144ff8d46c — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — Ascor L 500 (Ascorbic Acid Injection): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=2b71bd05-2891-34f2-e054-00144ff8d46c — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),

  ('acido-folico',
   E'Ácido fólico é a vitamina B9, essencial para fabricar glóbulos vermelhos e para o desenvolvimento do bebé na gravidez. A falta causa anemia; em grávidas, previne graves malformações do tubo neural do feto.',
   E'Folic acid is vitamin B9, essential for making red blood cells and for the baby\u2019s development in pregnancy. Deficiency causes anaemia; in pregnant women, it prevents serious neural tube defects.',
   E'Vitamina hidrossolúvel convertida em tetrahidrofolato, co-factor de reações de transferência de carbono na síntese de purinas e timidilato (ADN). A deficiência gera anemia macrocítica. O ácido fólico é o precursor estável usado na suplementação; a antagonização por metotrexato e trimetoprim/sulfametoxazol é a base farmacológica de interações importantes.',
   E'Water-soluble vitamin converted to tetrahydrofolate, cofactor of one-carbon transfer reactions in purine and thymidylate synthesis (DNA). Deficiency causes macrocytic anaemia. Folic acid is the stable precursor used in supplementation; antagonism by methotrexate and trimethoprim/sulfamethoxazole underlies important interactions.',
   E'• Anemia macrocítica por deficiência de folato\\n• Suplementação na gravidez (400 mcg/dia; 5 mg se risco elevado de defeitos do tubo neural)\\n• Profilaxia com metotrexato (baixa dose, uma vez por semana)\\n• Deficiência associada ao alcoolismo, má absorção e anemia hemolítica crónica',
   E'• Macrocytic anaemia from folate deficiency\\n• Pregnancy supplementation (400 mcg/day; 5 mg if high neural tube defect risk)\\n• Methotrexate prophylaxis (low dose, once weekly)\\n• Deficiency associated with alcoholism, malabsorption and chronic haemolytic anaemia',
   E'• Muito bem tolerada nas doses habituais\\n• Náuseas, dor abdominal e alteração do apetite (dose alta)\\n• Máscara hematológica: o folato pode corrigir a anemia mas esconder défice de B12 com degeneração neurológica progressiva\\n• Reações alérgicas (muito raro)\\n• Procure ajuda imediata se houver sinais de reação alérgica grave (dificuldade em respirar, inchaço do rosto/garganta).',
   E'• Very well tolerated at usual doses\\n• Nausea, abdominal pain and appetite change (high dose)\\n• Haematological mask: folate may correct anaemia but hide B12 deficiency with progressive neurological degeneration\\n• Allergic reactions (very rare)\\n• Seek immediate help if there are signs of a severe allergic reaction (trouble breathing, face/throat swelling).',
   E'• Sempre excluir défice de B12 antes de folato isolado em anemia macrocítica\\n• A tomada no mesmo dia do metotrexato (semana) pode reduzir a eficácia deste — seguir o esquema acordado\\n• Espaçar do sulfametoxazol/trimetoprim se possível\\n• Dose de gravidez: 400–800 mcg/dia, iniciada antes da conceção',
   E'• Always exclude B12 deficiency before isolated folate in macrocytic anaemia\\n• Same-day dosing with methotrexate (weekly) may reduce its efficacy — follow the agreed schedule\\n• Space from sulfamethoxazole/trimethoprim if possible\\n• Pregnancy dose: 400–800 mcg/day, started before conception',
   E'Rótulo aprovado DailyMed/FDA — Folic Acid (com rótulos combinados, ver referencia em EMC-UK Folic Acid Tablets): https://www.medicines.org.uk/emc/product/4095 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — Folic Acid (combined-label references; see EMC-UK Folic Acid Tablets): https://www.medicines.org.uk/emc/product/4095 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),

  ('sulfato-ferroso',
   E'Sulfato ferroso é um suplemento de ferro usado para tratar e prevenir a anemia por falta de ferro, a forma mais comum de anemia no mundo. Melhora a fadiga, a palidez e a falta de ar em poucas semanas.',
   E'Ferrous sulfate is an iron supplement used to treat and prevent iron-deficiency anaemia, the most common anaemia worldwide. It improves tiredness, pallor and shortness of breath within a few weeks.',
   E'Sal ferroso (Fe2+) absorvido no duodeno via transportador DMT1; a vitamina C melhora a absorção, os fitatos, taninos e antiácidos reduzem-na. O ferro incorpora-se em hemoglobina, mioglobina e depósitos (ferritina). A sobrecarga crónica lesa fígado, coração e pâncreas — nunca dar ferro por conta própria em doses altas prolongadas.',
   E'Ferrous (Fe2+) salt absorbed in the duodenum via the DMT1 transporter; vitamin C improves absorption, while phytates, tannins and antacids reduce it. Iron is incorporated into haemoglobin, myoglobin and stores (ferritin). Chronic overload damages liver, heart and pancreas — never take prolonged high doses on your own.',
   E'• Anemia ferropénica confirmada (fadiga, palidez, hemograma típico)\\n• Profilaxia na gravidez (associado a ácido fólico)\\n• Deficiência em lactentes e pré-escolares com dieta pobre em ferro\\n• Doença crónica com perda de ferro (menorragia, hemorroidas, doença inflamatória intestinal)',
   E'• Confirmed iron-deficiency anaemia (fatigue, pallor, typical blood count)\\n• Prophylaxis in pregnancy (combined with folic acid)\\n• Deficiency in infants and preschoolers with iron-poor diets\\n• Chronic disease with iron loss (menorrhagia, haemorrhoids, inflammatory bowel disease)',
   E'• Fezes escuras (esperado e inofensivo)\\n• Náuseas, cólicas, obstipação ou diarreia\\n• Gosto metálico e escurecimento da língua (soluções líquidas)\\n• Sobredosagem em crianças é EMERGÊNCIA: necrose gástrica, choque, acidose\\n• Procure ajuda imediata se uma criança engolir comprimidos de ferro.',
   E'• Dark stools (expected and harmless)\\n• Nausea, cramps, constipation or diarrhoea\\n• Metallic taste and tongue staining (liquid forms)\\n• Overdose in children is an EMERGENCY: gastric necrosis, shock, acidosis\\n• Seek immediate help if a child swallows iron tablets.',
   E'• Tomar em jejum aumenta a absorção; com alimento reduz o desconforto — escolher pelo balanceamento\\n• Espaçar do chá, café, leite, antiácidos e tetraciclinas (≥ 2 h)\\n• Combinar com vitamina C (sumo de laranja) melhora a absorção\\n• Manter fora do alcance de crianças — embalagem segura',
   E'• Fasting dosing improves absorption; with food reduces discomfort — balance choice\\n• Space from tea, coffee, milk, antacids and tetracyclines (≥ 2 h)\\n• Combining with vitamin C (orange juice) improves absorption\\n• Keep out of children\u2019s reach — child-resistant packaging',
   E'Rótulo aprovado DailyMed/FDA — Ferrous Sulfate 325 mg Tablet: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5599f519-766c-4f34-84cf-d314d0a550aa — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — Ferrous Sulfate 325 mg Tablet: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5599f519-766c-4f34-84cf-d314d0a550aa — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),

  ('vitamina-d',
   E'Vitamina D (colecalciferol) é a vitamina do sol, essencial para absorver cálcio e manter os ossos fortes. A falta causa raquitismo nas crianças e osteomalácia/osteoporose nos adultos.',
   E'Vitamin D (cholecalciferol) is the sunshine vitamin, essential for absorbing calcium and keeping bones strong. Deficiency causes rickets in children and osteomalacia/osteoporosis in adults.',
   E'Vitamina lipossolúvel sintetizada na pele por UVB e ativada em duas etapas (fígado → 25-OH-D; rim → 1,25-(OH)2-D ativa). A forma ativa aumenta a absorção intestinal de cálcio e fósforo e regula a remodelação óssea. Armazenamento adiposo explica a duração prolongada do efeito e o risco de toxicidade cumulativa com doses altas crónicas.',
   E'Fat-soluble vitamin synthesised in skin by UVB and activated in two steps (liver → 25-OH-D; kidney → active 1,25-(OH)2-D). The active form increases intestinal calcium and phosphate absorption and regulates bone remodelling. Adipose storage explains the prolonged effect and cumulative toxicity risk with chronic high doses.',
   E'• Prevenção e tratamento do raquitismo e osteomalácia\\n• Deficiência documentada (25-OH-D baixo) em idosos, gestantes e doentes com pouca exposição solar\\n• Adjuvante do cálcio na osteoporose\\n• Hipoparatiroidismo (com cálcio, sob supervisão)',
   E'• Prevention and treatment of rickets and osteomalacia\\n• Documented deficiency (low 25-OH-D) in the elderly, pregnant women and patients with little sun exposure\\n• Adjunct to calcium in osteoporosis\\n• Hypoparathyroidism (with calcium, under supervision)',
   E'• Toxicidade por excesso (hipercalcemia): sede, urina abundante, náuseas, confusão, dor óssea\\n• Deposita cálcio em rins e vasos (nefrocalcinose) em tratamentos crónicos em dose alta\\n• Nas doses habituais de suplementação é muito bem tolerada\\n• Procure ajuda imediata se houver confusão, sede intensa ou diminuição da urina durante tratamentos prolongados.',
   E'• Toxicity from excess (hypercalcaemia): thirst, abundant urine, nausea, confusion, bone pain\\n• Calcium deposits in kidneys and vessels (nephrocalcinosis) on chronic high-dose treatment\\n• At usual supplementation doses it is very well tolerated\\n• Seek immediate help if confusion, intense thirst or reduced urination occurs during prolonged treatment.',
   E'• Dose alta diária não é melhor que semanal/mensal — seguir o esquema prescrito\\n• Vigiar cálcio sérico e 25-OH-D em tratamentos prolongados ou dose > 2000 UI/dia\\n• Cuidado com multivitamínicos que já contêm vitamina D (duplicação)\\n• Em doença renal crónica, usar as formas ativas apenas com supervisão nefrológica',
   E'• High daily dosing is not better than weekly/monthly — follow the prescribed schedule\\n• Monitor serum calcium and 25-OH-D in prolonged treatment or doses > 2000 IU/day\\n• Beware of multivitamins that already contain vitamin D (duplication)\\n• In chronic kidney disease, use active forms only under nephrology supervision',
   E'Rótulo aprovado DailyMed/FDA — Cholecalciferol (vitamina D3): ver também Prontuário Terapêutico do INFARMED (11.ª ed., 2012) — fontes DailyMed consultadas: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=3a1f0405-6983-410d-b625-54517a6a235f',
   E'DailyMed/FDA approved label — Cholecalciferol (vitamin D3): see also Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012) — DailyMed sources consulted: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=3a1f0405-6983-410d-b625-54517a6a235f'),

  ('calcio',
   E'Cálcio (carbonato de cálcio) é um mineral essencial para ossos, dentes, contração muscular e coagulação. Serve como suplemento na osteoporose e na gravidez, e como antiácido ocasional na azia.',
   E'Calcium (calcium carbonate) is an essential mineral for bones, teeth, muscle contraction and clotting. It serves as a supplement in osteoporosis and pregnancy, and as an occasional antacid in heartburn.',
   E'Sal de cálcio oral com absorção dependente da vitamina D e do pH gástrico (melhor com refeição). Além do papel mineral, o carbonato de cálcio tampona o HCl gástrico como antiácido. Interage com tetraciclinas, quinolonas, levotiroxina, ferro e bifosfonatos (quelação na luz intestinal). A sobrecarga crónica em dose alta pode causar síndrome leite-álcali e litíase.',
   E'Oral calcium salt with absorption dependent on vitamin D and gastric pH (better with a meal). Beyond its mineral role, calcium carbonate buffers gastric HCl as an antacid. Interacts with tetracyclines, quinolones, levothyroxine, iron and bisphosphonates (intestinal chelation). Chronic overload at high dose can cause milk-alkali syndrome and lithiasis.',
   E'• Suplementação na gravidez e lactação (especialmente se a dieta for pobre)\\n• Osteoporose e osteopenia (com vitamina D)\\n• Hipocalcemia oral documentada\\n• Antiácido ocasional na dispepsia/azia (dose curta)',
   E'• Supplementation in pregnancy and lactation (especially with a poor diet)\\n• Osteoporosis and osteopenia (with vitamin D)\\n• Documented oral hypocalcaemia\\n• Occasional antacid in dyspepsia/heartburn (short course)',
   E'• Obstipação, gases e desconforto abdominal\\n• Risco de cálculos renais em doses altas crónicas\\n• Síndrome leite-álcali (cálcio + antiácido em dose alta prolongada): náuseas, cefaleia, confusão\\n• Hipercalcemia por excesso: fadiga, sede, urina abundante\\n• Procure ajuda imediata se houver confusão, sede intensa ou diminuição da urina durante tratamentos prolongados.',
   E'• Constipation, gas and abdominal discomfort\\n• Kidney stone risk with chronic high doses\\n• Milk-alkali syndrome (calcium + antacid at prolonged high dose): nausea, headache, confusion\\n• Hypercalcaemia from excess: fatigue, thirst, abundant urine\\n• Seek immediate help if confusion, intense thirst or reduced urination occurs during prolonged treatment.',
   E'• Espaçar 2–4 h de levotiroxina, tetraciclinas, quinolonas, ferro e bifosfonatos\\n• Tomar com refeição melhora a absorção\\n• Não exceder 2000–2500 mg/dia de cálcio elementar de todas as fontes\\n• Em litíase renal prévia, evitar suplementação sem avaliação',
   E'• Space 2–4 h from levothyroxine, tetracyclines, quinolones, iron and bisphosphonates\\n• Taking with a meal improves absorption\\n• Do not exceed 2000–2500 mg/day of elemental calcium from all sources\\n• With previous kidney stones, avoid supplementation without assessment',
   E'Rótulo aprovado DailyMed/FDA — Calcium Carbonate (antacid): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=25db68f7-af79-4a43-ac16-469ff08d64b8 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — Calcium Carbonate (antacid): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=25db68f7-af79-4a43-ac16-469ff08d64b8 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),

  ('noreisterona',
   E'Noretisterona é um gestagénio (hormona parecida com a progesterona) usado na pílula só com gestagénio, no tratamento de menstruações muito abundantes ou dolorosas e na endometriose.',
   E'Norethisterone is a progestogen (a hormone similar to progesterone) used in the progestogen-only pill, for treating very heavy or painful periods, and in endometriosis.',
   E'19-nortestosterona com forte atividade progestogénica e ligeira atividade androgénica residual. Transforma o endométrio proliferativo em secretor, engrossa o muco cervical e inibe a ovulação em dose contraceptiva. Metabolismo hepático (CYP3A4) — indutores enzimáticos comprometem a eficácia contraceptiva.',
   E'19-nortestosterone with strong progestogenic activity and slight residual androgenic activity. Converts proliferative endometrium to secretory, thickens cervical mucus and inhibits ovulation at contraceptive dose. Hepatic metabolism (CYP3A4) — enzyme inducers compromise contraceptive efficacy.',
   E'• Contracepção só com gestagénio (pílula "mini")\\n• Menorragia funcional e dismenorreia severa\\n• Endometriose (sintomas dolorosos)\\n• Amenorreia secundária e síndrome pré-menstrual (casos selecionados)',
   E'• Progestogen-only contraception (the "mini" pill)\\n• Functional menorrhagia and severe dysmenorrhoea\\n• Endometriosis (painful symptoms)\\n• Secondary amenorrhoea and premenstrual syndrome (selected cases)',
   E'• Sangramento irregular e spotting (muito comum)\\n• Mastalgia, alteração do humor e acne\\n• Cefaleias\\n• Risco trombótico inferior ao dos contracetivos combinados, mas não nulo\\n• Procure ajuda imediata se houver dor torácica súbita, falta de ar ou perda de força num lado do corpo.',
   E'• Irregular bleeding and spotting (very common)\\n• Breast tenderness, mood change and acne\\n• Headaches\\n• Thrombotic risk lower than combined contraceptives, but not nil\\n• Seek immediate help if there is sudden chest pain, shortness of breath or loss of strength on one side of the body.',
   E'• Eficácia comprometida por rifampicina, anticonvulsivantes indutores e griseofulvina — usar duplo método\\n• Iniciar preferencialmente nos primeiros 5 dias do ciclo\\n• Vigiar tensão arterial antes e durante o uso\\n• Não usar em doença hepática ativa ou antecedente de cancro da mama',
   E'• Efficacy compromised by rifampicin, inducing anticonvulsants and griseofulvin — use dual method\\n• Preferably start within the first 5 days of the cycle\\n• Monitor blood pressure before and during use\\n• Do not use in active liver disease or history of breast cancer',
   E'Rótulo aprovado DailyMed/FDA — Nora-BE (Norethindrone) Tablet [Teva]: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=426ac898-7745-4645-bf9b-bae319e260e8 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — Nora-BE (Norethindrone) Tablet [Teva]: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=426ac898-7745-4645-bf9b-bae319e260e8 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),

  ('levonorgestrel-etinilestradiol',
   E'Levonorgestrel + etinilestradiol é a pílula contracetiva combinada: uma hormona progestogénica e um estrogénio que juntas impedem a ovulação. Quando tomada corretamente é mais de 99% eficaz.',
   E'Levonorgestrel + ethinylestradiol is the combined contraceptive pill: a progestogenic hormone and an oestrogen that together prevent ovulation. When taken correctly it is more than 99% effective.',
   E'Associação de progestagénio (levonorgestrel) e estrogénio sintético (etinilestradiol) que suprime a ovulação por retroalimentação hipotalâmica (FSH/LH), altera o muco cervical e atrofia o endométrio. Primeira passagem hepática do etinilestradiol justifica interação crítica com indutores enzimáticos (rifampicina, carbamazepina, fenitoína, griseofulvina, Hypericum).',
   E'Combination of progestogen (levonorgestrel) and synthetic oestrogen (ethinylestradiol) that suppresses ovulation via hypothalamic feedback (FSH/LH), alters cervical mucus and atrophies the endometrium. Ethinylestradiol first-pass hepatic metabolism underlies critical interactions with enzyme inducers (rifampicin, carbamazepine, phenytoin, griseofulvin, St John\u2019s wort).',
   E'• Contracepção oral feminina (efeito principal)\\n• Regularização de ciclos irregulares e dismenorreia\\n• Acne hormonal em mulheres que também pretendem contracetivo\\n• Redução do risco de quisto ovárico funcional',
   E'• Female oral contraception (main effect)\\n• Regulation of irregular cycles and dysmenorrhoea\\n• Hormonal acne in women who also want contraception\\n• Reduced risk of functional ovarian cyst',
   E'• Náuseas, mastalgia e cefaleias (sobretudo nos primeiros 3 meses)\\n• Sangramento intermenstrual e amenorreia pós-pílula\\n• Aumento da tensão arterial\\n• Risco acrescido de trombose venosa profunda e embolia pulmonar; AVC e enfarte (raro, aumenta com idade/tabaco)\\n• Procure ajuda imediata se houver dor torácica súbita, falta de ar, dor de perna com inchaço, perda súbita de visão ou de força num lado.',
   E'• Nausea, breast tenderness and headaches (mostly in the first 3 months)\\n• Intermenstrual bleeding and post-pill amenorrhoea\\n• Blood pressure increase\\n• Increased risk of deep vein thrombosis and pulmonary embolism; stroke and heart attack (rare, increases with age/smoking)\\n• Seek immediate help if there is sudden chest pain, shortness of breath, leg pain with swelling, sudden loss of vision or strength on one side.',
   E'• Contra-indicado: fumadoras ≥ 35 anos, enxaqueca com aura, antecedente de trombose, doença hepática, cancro hormono-dependente\\n• Indutores enzimáticos anulam a eficácia — usar duplo método\\n• Vigiar tensão arterial regularmente\\n• Suspender 4 semanas antes de cirurgia de grande porte ou imobilização prolongada',
   E'• Contraindicated: smokers ≥ 35 years, migraine with aura, history of thrombosis, liver disease, hormone-dependent cancer\\n• Enzyme inducers nullify efficacy — use dual method\\n• Monitor blood pressure regularly\\n• Stop 4 weeks before major surgery or prolonged immobilisation',
   E'Rótulo aprovado DailyMed/FDA — Camrese (Levonorgestrel/Ethinyl Estradiol): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=0e198d28-4986-4b93-833f-17c7ed4ce13e — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — Camrese (Levonorgestrel/Ethinyl Estradiol): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=0e198d28-4986-4b93-833f-17c7ed4ce13e — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),

  ('desmopressina',
   E'Desmopressina é um medicamento parecido com a hormona antidiurética natural. Serve para reduzir a urina abundante na diabetes insípida, para a falta de hormona do crescimento do sono (enurese noturna) e em alguns tipos de hemorragia.',
   E'Desmopressin is a medicine similar to the natural antidiuretic hormone. It is used to reduce excessive urine in diabetes insipidus, for nighttime bedwetting, and in some types of bleeding.',
   E'Análogo sintético da vasopressina (des-amino D-arginina vasopressina) com seletividade pelo recetor V2 renal: aumenta a reabsorção de água no túbulo coletor e libera fator de von Willebrand/fator VIII das células endoteliais (útil na hemofilia ligeira e doença de von Willebrand tipo 1). Metabolismo peptidase mínimo → duração prolongada (8–12 h intranasal/oral).',
   E'Synthetic vasopressin analogue (de-amino D-arginine vasopressin) with renal V2 receptor selectivity: increases water reabsorption in the collecting tubule and releases von Willebrand factor/factor VIII from endothelial cells (useful in mild haemophilia and type 1 von Willebrand disease). Minimal peptidase metabolism → prolonged duration (8–12 h intranasal/oral).',
   E'• Diabetes insípida central\\n• Enurese noturna (a partir dos 5–6 anos)\\n• Hemofilia A ligeira e doença de von Willebrand tipo 1 (procedimentos menores)\\n• Poliúria pós-hipofisectomia',
   E'• Central diabetes insipidus\\n• Nocturnal enuresis (from age 5–6)\\n• Mild haemophilia A and type 1 von Willebrand disease (minor procedures)\\n• Post-hypophysectomy polyuria',
   E'• Dor de cabeça, náuseas, dor abdominal\\n• Hiponatremia por retenção de água (o risco mais sério): confusão, cefaleia intensa, vómitos, convulsões\\n• Irritação da mucosa nasal (forma intranasal)\\n• Rubor facial e tontura\\n• Procure ajuda imediata se houver confusão, cefaleia intensa ou vómitos durante o tratamento (risco de sódio baixo).',
   E'• Headache, nausea, abdominal pain\\n• Hyponatraemia from water retention (the most serious risk): confusion, intense headache, vomiting, seizures\\n• Nasal mucosa irritation (intranasal form)\\n• Facial flushing and dizziness\\n• Seek immediate help if confusion, intense headache or vomiting occurs during treatment (low sodium risk).',
   E'• CRÍTICO: restringir ingestão de líquidos 1 h antes até 8 h depois da toma (risco de hiponatremia)\\n• Interromper durante vómitos/diarreia ou antes de cirurgia com fluidoterapia livre\\n• Vigiar sódio sérico em idosos e crianças\\n• Não usar na doença de von Willebrand tipo 2B ou hemofilia moderada/grave',
   E'• CRITICAL: restrict fluid intake 1 h before to 8 h after dosing (hyponatraemia risk)\\n• Stop during vomiting/diarrhoea or before surgery with free fluid therapy\\n• Monitor serum sodium in the elderly and children\\n• Do not use in type 2B von Willebrand disease or moderate/severe haemophilia',
   E'Rótulo aprovado DailyMed/FDA — Desmopressin Acetate: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=abe23504-ea98-4ed9-9a9a-6db9eaa35251 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — Desmopressin Acetate: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=abe23504-ea98-4ed9-9a9a-6db9eaa35251 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),

  ('neostigmina',
   E'Neostigmina é um medicamento usado no fim de cirurgias para reverter o efeito dos relaxantes musculares, permitindo que o doente respire e se mova normalmente. Também é usado em problemas intestinais e urinários agudos por falta de tónus.',
   E'Neostigmine is a medicine used at the end of surgeries to reverse the effect of muscle relaxants, allowing the patient to breathe and move normally. It is also used in acute bowel and urinary problems from lack of tone.',
   E'Inibidor reversível da acetilcolinesterase: acumula acetilcolina na fenda neuromuscular, deslocando o bloqueante não-despolarizante do recetor nicotínico. Ação muscarínica acompanhante (bradicardia, secreções, peristalse) exige anticolinérgico de apoio (atropina/glicopirónio). Início 5–10 min IV, pico 8–12 min, duração 1–2 h.',
   E'Reversible acetylcholinesterase inhibitor: acetylcholine accumulates in the neuromuscular cleft, displacing the non-depolarising blocker from the nicotinic receptor. Accompanying muscarinic action (bradycardia, secretions, peristalsis) requires anticholinergic support (atropine/glycopyrronium). IV onset 5–10 min, peak 8–12 min, duration 1–2 h.',
   E'• Reversão do bloqueio neuromuscular não despolarizante no fim da anestesia\\n• Íleo paralítico e atonia vesical pós-operatórios\\n• Miastenia grave (diagnóstico diferencial com edrofónio; tratamento com piridostigmina preferido)\\n• Toxicidade por anticolinérgicos (uso não rotulado, com monitorização)',
   E'• Reversal of non-depolarising neuromuscular blockade at the end of anaesthesia\\n• Post-operative paralytic ileus and bladder atony\\n• Myasthenia gravis (differential diagnosis with edrophonium; pyridostigmine preferred for treatment)\\n• Anticholinergic toxicity (off-label use, with monitoring)',
   E'• Bradicardia, hipotensão e síncope (prevenir com atropina)\\n• Salivação intensa, suores, lágrimas e broncoespasmo (atividade muscarínica)\\n• Cãibras e fasciculações musculares\\n• Em excesso: fraqueza paradoxal (crise colinérgica)\\n• Procure ajuda imediata se houver falta de ar, sibilância intensa ou batimentos muito lentos.',
   E'• Bradycardia, hypotension and syncope (prevent with atropine)\\n• Profuse salivation, sweating, tears and bronchospasm (muscarinic activity)\\n• Muscle cramps and fasciculations\\n• In excess: paradoxical weakness (cholinergic crisis)\\n• Seek immediate help if there is shortness of breath, intense wheezing or very slow heartbeat.',
   E'• Administrar só após confirmação de recuperação clínica (TOF ≥ 2 respostas) e com monitorização\\n• Associar sempre antimuscarínico em ambiente de anestesia\\n• Dose máxima adulta ~ 5 mg IV por reversão — excesso piora a fraqueza\\n• Cuidado em asma, bradicardia, doença de Parkinson e obstrução gastrointestinal mecânica',
   E'• Administer only after confirmed clinical recovery (TOF ≥ 2 responses) with monitoring\\n• Always combine with an antimuscarinic in the anaesthesia setting\\n• Adult reversal max ~ 5 mg IV — excess worsens weakness\\n• Caution in asthma, bradycardia, Parkinson\u2019s disease and mechanical GI obstruction',
   E'Rótulo aprovado DailyMed/FDA — Neostigmine Methylsulfate Injection [Gland Pharma]: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4eab6184-1771-4c15-a127-4eb3e47affc2 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — Neostigmine Methylsulfate Injection [Gland Pharma]: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4eab6184-1771-4c15-a127-4eb3e47affc2 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),

  ('vecuronio',
   E'Vecurônio é um relaxante muscular usado durante anestesias e intubações: paralisia temporária dos músculos para permitir que o cirurgião opere com segurança enquanto o doente está dormindo e ventilado.',
   E'Vecuronium is a muscle relaxant used during anaesthesia and intubations: temporary muscle paralysis to allow the surgeon to operate safely while the patient is asleep and ventilated.',
   E'Bloqueante neuromuscular não despolarizante aminoesteróide: compete com a acetilcolina no recetor nicotínico da placa motora (bloqueio competitivo). Início 2–3 min IV, duração 25–40 min em dose de intubação. Eliminação hepatobiliar e renal; efeito prolongado em doença hepática/renal avançada e hipotermia. Reversível por neostigmina/sugamadex.',
   E'Aminosteroid non-depolarising neuromuscular blocker: competes with acetylcholine at the motor end-plate nicotinic receptor (competitive block). IV onset 2–3 min, duration 25–40 min at intubating dose. Hepatobiliary and renal elimination; prolonged effect in advanced liver/kidney disease and hypothermia. Reversible by neostigmine/sugammadex.',
   E'• Facilitação da intubação traqueal\\n• Relaxamento muscular cirúrgico sob anestesia geral com ventilação controlada\\n• Sincronização da ventilação mecânica em cuidados intensivos\\n• Controlo de convulsões refratárias ou tétano (uso especializado)',
   E'• Facilitation of tracheal intubation\\n• Surgical muscle relaxation under general anaesthesia with controlled ventilation\\n• Mechanical ventilation synchronisation in intensive care\\n• Control of refractory seizures or tetanus (specialised use)',
   E'• Paralisia voluntária total (esperada) — o doente fica consciente se a anestesia for insuficiente\\n• Hipotensão leve e taquicardia rara (menos histamina que o atracúrio)\\n• Paralisia prolongada em doentes críticos (miopatia do doente crítico)\\n• Anafilaxia (raro)\\n• Procure ajuda imediata se houver sinais de reação alérgica grave (dificuldade em respirar, inchaço do rosto/garganta).',
   E'• Total voluntary paralysis (expected) — patient may be aware if anaesthesia is insufficient\\n• Mild hypotension and rare tachycardia (less histamine than atracurium)\\n• Prolonged paralysis in critically ill patients (critical illness myopathy)\\n• Anaphylaxis (rare)\\n• Seek immediate help if there are signs of a severe allergic reaction (trouble breathing, face/throat swelling).',
   E'• Uso EXCLUSIVO em ambiente com via aérea garantida e ventilação mecânica\\n• Garantir amnésia/anestesia profunda antes de injetar (risco de consciência com paralisia)\\n• Monitorizar bloqueio com estimulador de nervo (TOF)\\n• Ajustar dose na doença hepática/renal avançada e na miastenia',
   E'• EXCLUSIVE use in settings with secured airway and mechanical ventilation\\n• Ensure amnesia/deep anaesthesia before injection (awareness-with-paralysis risk)\\n• Monitor block with nerve stimulator (TOF)\\n• Adjust dose in advanced liver/kidney disease and myasthenia',
   E'Rótulo aprovado DailyMed/FDA — Vecuronium Bromide Injection: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=582c7f44-b614-18df-e063-6294a90a74b6 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — Vecuronium Bromide Injection: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=582c7f44-b614-18df-e063-6294a90a74b6 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),

  ('suxametonio',
   E'Suxametónio (succinilcolina) é o relaxante muscular de ação ultrarrápida usado para colocar o tubo de respiração em urgências (estômago cheio) e em procedimentos de curta duração. Paralisa os músculos em menos de um minuto e o efeito passa em 5–10 minutos.',
   E'Succinylcholine is the ultra-short-acting muscle relaxant used to place the breathing tube in emergencies (full stomach) and in short procedures. It paralyses muscles in under a minute and the effect wears off in 5–10 minutes.',
   E'Único bloqueante despolarizante em uso: mimetiza a acetilcolina no recetor nicotínico e produz fasciculações seguidas de paralisia (fase I). Hidrólise rápida pela butirilcolinesterase plasmática — duração 5–10 min. Pode desencadear hiperpotassemia grave (denervação, queimaduras, trauma) e hipertermia maligna em predispostos.',
   E'The only depolarising blocker in use: mimics acetylcholine at the nicotinic receptor and produces fasciculations followed by paralysis (phase I). Rapid hydrolysis by plasma butyrylcholinesterase — duration 5–10 min. Can trigger severe hyperkalaemia (denervation, burns, trauma) and malignant hyperthermia in predisposed patients.',
   E'• Intubação de sequência rápida (estômago cheio, urgência)\\n• Laringospasmo refratário\\n• Eletroconvulsoterapia (relaxamento muscular curto)\\n• Procedimentos breves que exijam paralisia momentânea',
   E'• Rapid sequence intubation (full stomach, emergency)\\n• Refractory laryngospasm\\n• Electroconvulsive therapy (short muscle relaxation)\\n• Brief procedures requiring momentary paralysis',
   E'• Fasciculações visíveis e dores musculares nos dias seguintes\\n• Hiperpotassemia potencialmente fatal em doentes com queimaduras, trauma, denervação ou imobilização prolongada\\n• Bradicardia (repetição de doses)\\n• Hipertermia maligna (raro, mas potencialmente letal): rigidez, febre rápida, acidose\\n• História de anafilaxia\\n• Procure ajuda imediata se houver rigidez muscular com febre rápida após a anestesia.',
   E'• Visible fasciculations and muscle aches in the following days\\n• Potentially fatal hyperkalaemia in patients with burns, trauma, denervation or prolonged immobilisation\\n• Bradycardia (repeated doses)\\n• Malignant hyperthermia (rare, but potentially lethal): rigidity, rapid fever, acidosis\\n• History of anaphylaxis\\n• Seek immediate help if muscle rigidity with rapid fever occurs after anaesthesia.',
   E'• CONTRAINDICADO em hipertermia maligna prévia ou familiar, miopatias, denervação, queimaduras > 48 h e hiperpotassemia\\n• Nunca administrar por perfusão prolongada em cuidados intensivos (risco de miopatia)\\n• Ambiente com via aérea garantida e ventilação obrigatória\\n• Vigiar potássio em doentes de risco',
   E'• CONTRAINDICATED in previous/familial malignant hyperthermia, myopathies, denervation, burns > 48 h and hyperkalaemia\\n• Never administer as prolonged ICU infusion (myopathy risk)\\n• Setting with secured airway and mandatory ventilation\\n• Monitor potassium in at-risk patients',
   E'Rótulo aprovado DailyMed/FDA — Succinylcholine Chloride Injection: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=efe5a242-5ba0-4b14-844c-206a79850d81 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — Succinylcholine Chloride Injection: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=efe5a242-5ba0-4b14-844c-206a79850d81 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)')
) AS v(slug, overview_public_pt, overview_public_en, overview_pro_pt, overview_pro_en,
       indications_pt, indications_en, side_effects_pt, side_effects_en,
       precautions_pt, precautions_en, source_pt, source_en)
  ON d.slug = v.slug
ON CONFLICT (drug_id) DO NOTHING;
